@layer nz.tokens, nz.themes, nz.reset, nz.base, nz.components, nz.patterns, nz.utilities;


@layer nz.components {
  .nz-kbd {
    display: inline-flex;
    align-items: center;
    padding-block: 1px;
    padding-inline: var(--nz-space-1-5);
    border: var(--nz-border-width-default) solid var(--nz-kbd-border, var(--nz-border-default));
    border-radius: var(--nz-kbd-radius, var(--nz-radius-xs));
    background: var(--nz-kbd-bg, var(--nz-bg-subtle));
    color: var(--nz-kbd-fg, var(--nz-text-secondary));
    font: var(--nz-font-mono-m);
    letter-spacing: var(--nz-tracking-mono-m);
    white-space: nowrap;
  }

  /* Without ThemeScript's data-nz-platform the "other" spelling shows (Ctrl+K). The hidden span is
     display: none, so assistive technology reads one spelling only. */
  .nz-kbd-glyphs[data-platform='apple'] {
    display: none;
  }

  :where([data-nz-platform='apple']) .nz-kbd-glyphs[data-platform='apple'] {
    display: inline;
  }

  :where([data-nz-platform='apple']) .nz-kbd-glyphs[data-platform='other'] {
    display: none;
  }

  @media (forced-colors: active) {
    .nz-kbd {
      border-color: CanvasText;
    }
  }

  /* Optical centring (M85, as Button's label): trimmed to cap height and baseline, padded back to
     one line, so the box keeps its height and the letters sit in its middle. */
  @supports (text-box: trim-both cap alphabetic) {
    .nz-kbd-label {
      padding-block: calc((1lh - 1cap) / 2);
      text-box: trim-both cap alphabetic;
    }
  }
}
